// Builds supabase/functions/check-alerts/index.ts from the app's own scoring modules + tools/alerts-main.js,
// so alerts always score sessions exactly like the app. Run from the project folder:  node tools/build-alerts.mjs
import fs from 'node:fs';

const MODULES = ['util', 'hunts', 'scoring', 'api'];   // dependency order
const header = `// @ts-nocheck
// GENERATED by tools/build-alerts.mjs from the app's js/ modules and tools/alerts-main.js.
// Don't edit this file directly: change those, then run  node tools/build-alerts.mjs  again.
import webpush from 'npm:web-push@3.6.7';
import SunCalc from 'npm:suncalc@1.9.0';
import { createClient } from 'npm:@supabase/supabase-js@2.45.4';

globalThis.window = globalThis;   // the app's modules look for window.SunCalc
globalThis.SunCalc = SunCalc;
`;

let out = header;
for (const m of MODULES) {
  let src = fs.readFileSync(`js/${m}.js`, 'utf8');
  src = src.replace(/^import\s*\{([^}]+)\}\s*from\s*'\.\/(\w+)\.js(?:\?v=[\d.]+)?';\s*$/gm, (_, names, dep) => {
    if (!MODULES.includes(dep)) throw new Error(`${m}.js imports ${dep}.js, which isn't bundled`);
    return `const {${names}} = M_${dep};`;
  });
  if (/^import\s/m.test(src)) throw new Error(`${m}.js has an import the bundler doesn't understand`);
  const names = [...src.matchAll(/^export\s+(?:async\s+)?(?:function\*?|const|let|class)\s+([A-Za-z_$][\w$]*)/gm)].map(x => x[1]);
  src = src.replace(/^export\s+/gm, '');
  out += `\n/* ===== js/${m}.js ===== */\nconst M_${m} = (() => {\n${src}\nreturn { ${names.join(', ')} };\n})();\n`;
}
out += '\n' + fs.readFileSync('tools/alerts-main.js', 'utf8');
fs.mkdirSync('supabase/functions/check-alerts', { recursive: true });
fs.writeFileSync('supabase/functions/check-alerts/index.ts', out);
console.log(`Built supabase/functions/check-alerts/index.ts (${out.split('\n').length} lines)`);
